TOOL_FN["seuils-effectif"] = function (v, H) {
  function blank(x) { return x === undefined || x === null || String(x).replace(/\s/g, "") === ""; }
  var share = "Selon l'effectif, le Code du travail impose des délégués du personnel et un règlement intérieur au-delà de 11 travailleurs, puis un comité d'entreprise et un CSST à partir de 50.";
  if (blank(v.effectif)) {
    return { value: "—", sub: "Renseignez le nombre de travailleurs employés habituellement.", note: "", hints: {}, share: "", agenda: null };
  }
  var n = H.num(v.effectif);
  if (n < 0) {
    return { value: "—", sub: "L'effectif saisi ne peut pas être négatif.", note: "", hints: {}, share: "", agenda: null };
  }
  var list = [], det = [];
  if (n > 11) {
    list.push("délégués du personnel");
    list.push("règlement intérieur");
    det.push("délégués du personnel (Art. 215)");
    det.push("règlement intérieur (Art. 235)");
  }
  if (n >= 50) {
    list.push("comité d'entreprise");
    list.push("CSST");
    det.push("comité d'entreprise (Art. 225)");
    det.push("Comité Sécurité et Santé au Travail (Art. 171)");
  }
  var value, sub;
  if (list.length === 0) {
    value = "Aucune de ces obligations";
    sub = "Avec " + H.plural(n, "travailleur", "travailleurs") + ", l'effectif ne dépasse pas 11 : aucun seuil n'est atteint.";
  } else {
    var txt = list.length === 2 ? (list[0] + " et " + list[1]) : (list[0] + ", " + list[1] + ", " + list[2] + " et " + list[3]);
    value = txt.charAt(0).toUpperCase() + txt.slice(1);
    sub = "Avec " + H.plural(n, "travailleur", "travailleurs") + " : " + det.join(", ") + ".";
  }
  var conv = n >= 50
    ? "La convention collective d'entreprise est conclue au sein du comité d'entreprise (Art. 241)."
    : "Sous 50 travailleurs, la convention collective d'entreprise est conclue avec les délégués du personnel (Art. 241).";
  var note = "Délégués du personnel et règlement intérieur : plus de 11 travailleurs. Comité d'entreprise (50 travailleurs permanents) et CSST : 50 travailleurs et plus. " + conv + " Un syndicat d'entreprise exige 7 membres (Art. 207). Art. 171, 207, 215, 225, 235, 241.";
  return { value: value, sub: sub, note: note, hints: {}, share: share, agenda: null };
};

TOOL_FN["controle-cdd"] = function (v, H) {
  function blank(x) { return x === undefined || x === null || String(x).replace(/\s/g, "") === ""; }
  var share = "Un CDD dure de 1 à 24 mois, avec au plus 2 renouvellements et 72 mois cumulés ; à partir de 2 renouvellements successifs, il devient un CDI (Code du travail, Art. 25).";
  if (blank(v.duree) || blank(v.renouvellements) || blank(v.total)) {
    return { value: "—", sub: "Renseignez la durée du contrat, le nombre de renouvellements et la durée totale cumulée.", note: "", hints: {}, share: "", agenda: null };
  }
  var duree = H.num(v.duree), ren = H.num(v.renouvellements), total = H.num(v.total);
  if (duree < 0 || ren < 0 || total < 0) {
    return { value: "—", sub: "Les valeurs saisies ne peuvent pas être négatives.", note: "", hints: {}, share: "", agenda: null };
  }
  if (total < duree) {
    return { value: "—", sub: "La durée totale cumulée ne peut pas être inférieure à la durée du contrat en cours.", note: "", hints: {}, share: "", agenda: null };
  }
  var pb = [], ok = [];
  if (duree >= 1 && duree <= 24) { ok.push("durée valable (" + H.fmtNum(duree) + " mois)"); }
  else { pb.push("durée de " + H.fmtNum(duree) + " mois hors de la plage de 1 à 24 mois"); }
  if (ren <= 2) { ok.push(H.plural(ren, "renouvellement", "renouvellements") + ", 2 au plus"); }
  else { pb.push(H.plural(ren, "renouvellement", "renouvellements") + " : plus de 2"); }
  if (total <= 72) { ok.push("total de " + H.fmtNum(total) + " mois, au plus 72"); }
  else { pb.push("total de " + H.fmtNum(total) + " mois : plus de 72 mois (6 ans)"); }
  var cdi = ren >= 2;
  var value, sub;
  if (cdi) {
    value = "Le CDD est transformé en CDI";
  } else if (pb.length > 0) {
    value = "CDD non conforme";
  } else {
    value = "CDD conforme";
  }
  sub = "";
  if (pb.length > 0) { sub += "À corriger : " + pb.join(" ; ") + ". "; }
  if (ok.length > 0) { sub += "Conforme : " + ok.join(" ; ") + ". "; }
  if (cdi) { sub += "À partir de 2 renouvellements successifs, le CDD se transforme automatiquement en CDI (Art. 25), à faire confirmer."; }
  sub = sub.replace(/\s+$/, "");
  var note = "Vérifications : durée de chaque contrat entre 1 et 24 mois ; 2 renouvellements au plus ; durée totale cumulée de 72 mois (6 ans) au plus. Une réembauche au même poste après une interruption d'au plus 3 mois compte comme un renouvellement. Art. 25, 27.";
  return { value: value, sub: sub, note: note, hints: {}, share: share, agenda: null };
};

