        var calc = el("div", "dl-calc");
        var lab = el("label", "hint", "Date de départ"); lab.setAttribute("for", "dl-" + i);
        var inp = el("input"); inp.type = "date"; inp.id = "dl-" + i; inp.setAttribute("data-gdl", String(i));
        var res = el("span", "dl-res"); res.id = "dlr-" + i; res.setAttribute("aria-live", "polite");
        var add = el("button", "btn btn-ghost btn-sm", "Ajouter à l'agenda"); add.hidden = true; add.id = "dla-" + i;
