    related(key, ["model", "tool"], 4).forEach(function (o) { ac.appendChild(itemRow(o)); });
    [["pros", "Parler à un professionnel", "Avocat, notaire, huissier ou médiateur"], ["agenda", "Ajouter une date à mon agenda", "Audience, échéance, rendez-vous"], ["vault", "Garder mes pièces dans mon coffre", "Contrats, courriers, preuves"]].forEach(function (a) {
      ac.appendChild(rowEl(a[0], a[1], a[2], { kind: a[0] }));
    });

    /* sources */
